css:
figure{width:calc(50vw + 60px); margin-right:calc(50% - 50vw); border-radius:24px 0 0 24px; overflow:hidden; box-shadow:0 12px 30px rgba(80,70,120,.10)}
figure.to-left{margin-left:calc(50% - 50vw); margin-right:0; border-radius:0 24px 24px 0}
/* テキストカードを画面左辺に密着させる場合 */
.hero-card{margin-left:calc(50% - 50vw); max-width:440px; padding:22px 32px 20px; background:#fff; position:relative; z-index:2}
/* 反復のうち1枚だけ切る */
.ph{aspect-ratio:1; border-radius:50%; overflow:hidden; object-fit:cover}
.ph--cut{margin-right:-8vw} .ph--whole{margin:40px 12vw 0 auto; width:34%}
section{overflow:hidden}
